-- Synthia Core — initial numbered schema migration
-- Source: schema.sql; intentionally idempotent for fresh and existing databases.
BEGIN;
CREATE EXTENSION IF NOT EXISTS "pgcrypto";
CREATE EXTENSION IF NOT EXISTS "pg_trgm";
DO $$ BEGIN CREATE TYPE gate_id AS ENUM ('G0','G1','G2','G3','G4','G5','G6','G7','G8','G9'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE baseline_kind AS ENUM ('B0','B1','B2','B3','B4'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE artifact_rev_state AS ENUM ('candidate','in_review','approved','rejected','superseded','invalidated'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE gate_sub_state AS ENUM ('preparing','submitted','checking','in_review','approved','rejected','withdrawn'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE baseline_state AS ENUM ('active','superseded','invalidated','retired'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE tool_run_state AS ENUM ('submitted','rejected','queued','preparing','running','succeeded','failed','cancelling','cancelled','timeout','lost','unknown_effect'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE run_class AS ENUM ('exploratory','gate_check','formal'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE trace_state AS ENUM ('candidate','in_review','approved','rejected','review_required','superseded','invalidated'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE approval_decision AS ENUM ('approve','reject','approve_with_actions','request_changes','revoke','confirm_no_impact','accept_waiver'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE actor_type AS ENUM ('human','agent','connector','system'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE data_classification AS ENUM ('UNCLASSIFIED','D1','D2','D3','D4'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS project (id text PRIMARY KEY, name text NOT NULL, scope text NOT NULL DEFAULT '', data_classification data_classification NOT NULL DEFAULT 'D1', standard_version text NOT NULL DEFAULT 'GB/T 33781-2017', target_part text NOT NULL DEFAULT 'xc7vx690tffg1761-2', toolchain_profile_ref text, created_at timestamptz NOT NULL DEFAULT now(), status text NOT NULL DEFAULT 'active');
CREATE TABLE IF NOT EXISTS process_instance (id text PRIMARY KEY, project_id text NOT NULL REFERENCES project(id), gate_profile_version text NOT NULL, current_gate gate_id NOT NULL DEFAULT 'G0', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS role_assignment (id text PRIMARY KEY, project_id text NOT NULL REFERENCES project(id), actor_type actor_type NOT NULL, actor_id text NOT NULL, role text NOT NULL, permissions jsonb NOT NULL DEFAULT '{}', assigned_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS artifact (id text PRIMARY KEY, project_id text NOT NULL REFERENCES project(id), artifact_type text NOT NULL, title text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS artifact_revision (id text PRIMARY KEY, artifact_id text NOT NULL REFERENCES artifact(id), project_id text NOT NULL REFERENCES project(id), version integer NOT NULL, state artifact_rev_state NOT NULL DEFAULT 'candidate', parent_revision_id text REFERENCES artifact_revision(id), content_hash text NOT NULL, content_location text NOT NULL, schema_version text NOT NULL DEFAULT 'v1', source_ids text[] NOT NULL DEFAULT '{}', data_classification data_classification NOT NULL DEFAULT 'D1', tool_model_provenance jsonb, change_reason text NOT NULL DEFAULT '', created_by text NOT NULL, created_by_type actor_type NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), review_ids text[] NOT NULL DEFAULT '{}', UNIQUE (artifact_id, version));
CREATE TABLE IF NOT EXISTS configuration_snapshot (id text PRIMARY KEY, project_id text NOT NULL REFERENCES project(id), member_revision_ids text[] NOT NULL, trace_relation_ids text[] NOT NULL DEFAULT '{}', gate_profile_version text NOT NULL, tool_model_policy_hash text NOT NULL, manifest_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), created_by text NOT NULL);
CREATE TABLE IF NOT EXISTS gate_submission (id text PRIMARY KEY, project_id text NOT NULL REFERENCES project(id), process_instance_id text NOT NULL REFERENCES process_instance(id), gate gate_id NOT NULL, snapshot_id text NOT NULL REFERENCES configuration_snapshot(id), state gate_sub_state NOT NULL DEFAULT 'preparing', submitter_id text NOT NULL, check_results jsonb, issues text[] NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), submitted_at timestamptz);
CREATE TABLE IF NOT EXISTS approval_record (id text PRIMARY KEY, project_id text NOT NULL REFERENCES project(id), gate_submission_id text NOT NULL REFERENCES gate_submission(id), decision approval_decision NOT NULL, approver_id text NOT NULL, approver_role text NOT NULL, authorization_basis text NOT NULL, reason text NOT NULL, issues text[] NOT NULL DEFAULT '{}', risks text[] NOT NULL DEFAULT '{}', waivers text[] NOT NULL DEFAULT '{}', check_results_hash text NOT NULL, signed_at timestamptz NOT NULL, signature_method text NOT NULL DEFAULT 'platform_token', client_audit_digest text, approved_gate_result_id text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS approved_gate_result (id text PRIMARY KEY, project_id text NOT NULL REFERENCES project(id), gate gate_id NOT NULL, gate_submission_id text NOT NULL REFERENCES gate_submission(id), approval_record_id text NOT NULL REFERENCES approval_record(id), snapshot_id text NOT NULL REFERENCES configuration_snapshot(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS baseline (id text PRIMARY KEY, project_id text NOT NULL REFERENCES project(id), kind baseline_kind NOT NULL, state baseline_state NOT NULL DEFAULT 'active', approved_gate_result_id text NOT NULL REFERENCES approved_gate_result(id), member_revision_ids text[] NOT NULL, trace_relation_ids text[] NOT NULL DEFAULT '{}', manifest_hash text NOT NULL, approval_record_id text NOT NULL REFERENCES approval_record(id), created_at timestamptz NOT NULL DEFAULT now(), superseded_by_baseline_id text REFERENCES baseline(id));
CREATE TABLE IF NOT EXISTS tool_run (id text PRIMARY KEY, project_id text NOT NULL, operation text NOT NULL, capability_version text NOT NULL DEFAULT 'v1', run_class run_class NOT NULL, state tool_run_state NOT NULL DEFAULT 'submitted', input_snapshot_id text REFERENCES configuration_snapshot(id), input_manifest_hash text, authorization_context jsonb NOT NULL DEFAULT '{}', toolchain_profile_hash text, connector_id text, worker_id text, command text, parameters jsonb, return_code integer, start_time timestamptz, end_time timestamptz, correlation_id text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS evidence (id text PRIMARY KEY, tool_run_id text NOT NULL REFERENCES tool_run(id), project_id text NOT NULL, artifact_id text NOT NULL, uri text NOT NULL, sha256 text NOT NULL, size_bytes bigint NOT NULL, media_type text NOT NULL, completeness text NOT NULL DEFAULT 'full' CHECK (completeness IN ('full','partial')), orphaned boolean NOT NULL DEFAULT false, corrupt boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS trace_relation (id text PRIMARY KEY, project_id text NOT NULL, source_type text NOT NULL, source_id text NOT NULL, target_type text NOT NULL, target_id text NOT NULL, relation_kind text NOT NULL, state trace_state NOT NULL DEFAULT 'candidate', basis text NOT NULL DEFAULT '', data_classification data_classification NOT NULL DEFAULT 'D1', created_by text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
INSERT INTO schema_migrations(version) VALUES ('0000_initial_schema') ON CONFLICT (version) DO NOTHING;
COMMIT;
